#include "th10/game/result_choice_menu.hpp"
namespace{void SetPhase(ResultChoiceState*s,int p,const ResultChoiceOps*o){s->phase=p;o->reset_timer(o->context);}void Select(ResultChoiceState*s,const ResultChoiceInput*i,const ResultChoiceOps*o){s->previous_selection=s->selection;if((i->held&0x10u)||(i->pressed&0x10u))o->move_selection(o->context,s,-1);if((i->held&0x20u)||(i->pressed&0x20u))o->move_selection(o->context,s,1);if(s->selection!=s->previous_selection){o->set_animation(o->context,s->selection);o->play_sound(o->context,12);}}}
// 0x00422C80 - result/continue choice state machine.
int ResultChoiceMenu_Update(ResultChoiceState*s,const ResultChoiceInput*i,ResultChoiceEnv*e,const ResultChoiceOps*o){switch(s->phase){case 1:if(s->timer>=10){s->phase=2;s->selection_count=e->continue_used?2:3;s->initialized=true;s->selection=0;o->set_animation(o->context,7);}break;case 2:Select(s,i,o);if(i->pressed&0x1001u){o->play_sound(o->context,10);if(s->selection==0){o->close_effect(o->context,0);SetPhase(s,3,o);}else if(s->selection==1){o->open_effect(o->context,116);SetPhase(s,e->continue_used?3:4,o);}else if(s->selection==2){o->open_effect(o->context,117);SetPhase(s,4,o);}}if(i->pressed&0x4000u){o->play_sound(o->context,10);o->open_effect(o->context,117);s->selection=2;SetPhase(s,3,o);}if(i->pressed&0x200u){o->play_sound(o->context,10);o->open_effect(o->context,116);s->selection=1;SetPhase(s,3,o);}if(i->pressed&8u){s->selection=0;o->close_effect(o->context,0);SetPhase(s,3,o);}break;case 3:if(s->timer>=12){s->phase=0;o->execute_choice(o->context,s->selection,e);}break;case 4:if(s->timer==20){s->selection_count=2;s->selection=s->previous_selection?1:0;s->initialized=true;o->set_animation(o->context,s->selection+14);}if(s->timer>=30){Select(s,i,o);if(i->pressed&0x1001u){o->play_sound(o->context,10);if(s->selection<2){o->open_effect(o->context,119+s->selection);SetPhase(s,5,o);}}if(i->pressed&8u){s->selection=0;o->close_effect(o->context,0);SetPhase(s,3,o);}}break;case 5:if(s->timer>=20){if(s->selection==0){o->close_effect(o->context,0);SetPhase(s,3,o);}else{o->close_effect(o->context,1);o->set_animation(o->context,s->selection+7);SetPhase(s,2,o);}}break;}return 1;}
